typedef struct node {
    int d;
    struct node* rest;    // en pekare till samma struct går bra, men inte structen själv
} node;
typedef node* List;

int x = 5, y = 10;
int* p = &x;
int** pp = &p;
*pp = &y;          // nu pekar p på y

int addFirst(List* l, int d) {
    node* n = createListNode(d);
    if (n == NULL) return 0;
    n->rest = *l;          // nya noden pekar på det gamla huvudet
    *l = n;                // huvudet pekar på nya noden
    return 1;
}

void removeFirst(List* l) {
    assert(!isEmpty(*l));  // precondition
    node* toRemove = *l;
    *l = (*l)->rest;
    free(toRemove);
}
